p-word-count:
def word_count(text):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return counts

p-fact:
def fact(n):
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

p-safe-int:
def safe_int(s):
    try:
        return int(s)
    except ValueError:
        return None

md-stack:
class Stack:
    def __init__(self):
        self.items = []
    def push(self, x):
        self.items.append(x)
    def pop(self):
        return self.items.pop() if self.items else None
    def peek(self):
        return self.items[-1] if self.items else None
    def is_empty(self):
        return not self.items
    def size(self):
        return len(self.items)

md-rect:
class Rectangle:
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h
    def perimeter(self):
        return 2 * (self.w + self.h)

