p-bubble:
def bubble_sort(items):
    d = list(items)
    for i in range(len(d)):
        for j in range(len(d) - 1 - i):
            if d[j] > d[j + 1]:
                d[j], d[j + 1] = d[j + 1], d[j]
    return d

p-binsearch:
def bsearch(items, target):
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

p-brackets:
def valid(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack

p-two-sum:
def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return (seen[target - x], i)
        seen[x] = i
